PAGES=DATA
MATH={
'local':[r'\phi_i(\mathbf x)=\exp\!\left(-\frac{\|\mathbf x-\boldsymbol\mu_i\|^2}{2\sigma_i^2}\right)',r'\sigma_i>0,\quad\phi_i(\boldsymbol\mu_i)=1'],
'linear':[r'\hat y_j=\sum_{i=1}^{m}w_{ij}\phi_i(\mathbf x)'],
'matrix':[r'\Phi\in\mathbb R^{m\times n},\quad\mathbf W\in\mathbb R^{m\times k}',r'\mathbf Y,\hat{\mathbf Y}\in\mathbb R^{k\times n},\quad\hat{\mathbf Y}=\mathbf W^\top\Phi'],
'solve':[r'E=\|\mathbf Y-\mathbf W^\top\Phi\|_F^2',r'\Phi\Phi^\top\mathbf W=\Phi\mathbf Y^\top',r'\mathbf W=(\Phi\Phi^\top)^{-1}\Phi\mathbf Y^\top',r'\mathbf W=(\Phi\Phi^\top)^\dagger\Phi\mathbf Y^\top'],
'xorinput':[r'\boldsymbol\mu_1=(0,0),\quad\boldsymbol\mu_2=(1,1)',r'2\sigma^2=1,\quad\phi_i=e^{-\|\mathbf x-\boldsymbol\mu_i\|^2}'],
'bias':[r'\tilde\Phi=\begin{pmatrix}\Phi\\\mathbf1^\top\end{pmatrix}\in\mathbb R^{3\times4}',r'\hat y=a\phi_1+a\phi_2+b'],
'xorweights':[r'a(1+e^{-2})+b=0',r'a(2e^{-1})+b=1',r'a=\frac{-1}{1+e^{-2}-2e^{-1}}\approx-2.502650',r'b=-a(1+e^{-2})\approx2.841347'],
'xorboundary':[r'\hat y=a(\phi_1+\phi_2)+b',r'\hat y\ge0.5\Longleftrightarrow\phi_1+\phi_2\le\frac{0.5-b}{a}\approx0.935547'],
'winner':[r'z=\arg\min_j\|\mathbf x-\mathbf w_j\|_2'],
'update':[r'\mathbf w_3^+=(0.8,0.8)+0.5(0.1,-0.1)=(0.85,0.75)',r'\mathbf w_2^+=(0.5,0.5)+0.5(0.4,0.2)=(0.7,0.6)',r'\mathbf w_1^+=(0.2,0.2)'],
'rule':[r'j\in\mathcal N_z:\quad\mathbf w_j^+=\mathbf w_j+\eta(\mathbf x-\mathbf w_j)',r'j\notin\mathcal N_z:\quad\mathbf w_j^+=\mathbf w_j',r'0<\eta\le1'],
'schedule':[r'\eta^{(\tau+1)}=\eta^{(0)}(1-\tau/t)',r'\tau=0,\ldots,t-1'],
'gaussian':[r'h_j=\exp\!\left(-\frac{\|\mathbf r_j-\mathbf r_z\|^2}{2s_\tau^2}\right)',r'\mathbf w_j^+=\mathbf w_j+\eta_\tau h_j(\mathbf x-\mathbf w_j)',r'\eta_\tau=0.5(1-\tau/4000)+0.01',r's_\tau=3(1-\tau/4000)+0.4'],
'grid':[r'\mathbf w^{(0)}=0.5+0.06\,\operatorname{Normal}(0,1)',r'\mathbf x_\tau\sim U([0,1]^2),\quad\tau=0,\ldots,3999'],
'practice1':[r'\boldsymbol\mu_1=(0,0),\quad\boldsymbol\mu_2=(1,1),\quad2\sigma^2=1',r'\mathbf x=(0.5,0.5),\quad(\phi_1,\phi_2)=?'],
'practice2':[r'\mathbf w_1=(0,0),\quad\mathbf w_2=(1,1),\quad\mathbf x=(0.8,0.6)',r'\eta=0.5,\quad z=?,\quad\mathbf w_z^+=?'],
}
